import {nextSession,shiftDate} from './model.js';
import {ensureDay,assertUnchanged} from './body.js';
import {findExerciseDemo,exerciseDemos} from './exercise-catalogue.js';
import {EQUIPMENT,workoutConfig,createSessionDraft,completedSet,sessionRecord,previousPerformance,personalRecords,weeklyVolume,progressionStatus,substitutionOptions,supersetNext,actualSets,correctWorkoutRecord} from './workout-studio-model.js';

const DRAFT_KEY='cams-health-workout-draft-v1';
export function createWorkoutStudio(ctx){
 const get=key=>typeof ctx[key]==='function'&&['data','date','units'].includes(key)?ctx[key]():ctx[key];
 const data=()=>get('data'),date=()=>get('date'),units=()=>get('units')||'metric',esc=ctx.esc;
 const uid=()=>ctx.id?ctx.id():crypto.randomUUID(),fmt=n=>n==null?'—':ctx.fmt?ctx.fmt(n):Number(n).toLocaleString(undefined,{maximumFractionDigits:1});
 const b=(label,act,extra='',cls='btn secondary')=>`<button type="button" class="${cls}" data-ws="${act}" ${extra}>${label}</button>`;
 const field=(name,label,value='',attrs='')=>`<label class="field">${label}<input name="${name}" value="${esc(value??'')}" ${attrs}></label>`;
 const readDraft=()=>{try{const raw=localStorage.getItem(DRAFT_KEY);if(!raw||raw.length>1000000)return null;const d=JSON.parse(raw);if(d.version!==1||typeof d.id!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!Array.isArray(d.exercises)||!d.exercises.length||d.exercises.length>100||d.exercises.some(e=>typeof e.name!=='string'||!Array.isArray(e.setLog)||e.setLog.length>100||e.setLog.some(s=>!s||typeof s.id!=='string'||!['working','warmup'].includes(s.kind)||!Number.isFinite(Date.parse(s.completedAt))||['reps','load','rir','rpe','durationSec'].some(k=>s[k]!=null&&!Number.isFinite(s[k])))))return null;return d;}catch{return null;}};
 let draft=readDraft(),configSession=null,restInterval=null,recordRoute=null;
 const keep=()=>{try{if(draft)localStorage.setItem(DRAFT_KEY,JSON.stringify(draft));else localStorage.removeItem(DRAFT_KEY);}catch{ctx.toast?.('Browser storage is unavailable. Keep this tab open to retain the session.');}};
 const setCount=()=>draft?.exercises.reduce((n,e)=>n+e.setLog.length,0)||0;
 const loadValue=(value,unit=units())=>value==null?null:value*(unit==='imperial'?2.20462262185:1);
 const loadLabel=unit=>(unit||units())==='imperial'?'lb':'kg';
 const clearance=()=>data().profile.trainingStatus==='ready'?'':`<p class="ws-clearance">${data().profile.trainingStatus==='paused'?'Training is paused.':'Exercise clearance is unconfirmed.'} You can review the plan and record what you actually performed. This tool does not change your clearance.</p>`;
 const note=(text)=>`<p class="help">${text}</p>`;
 const shell=(content,tab='tools')=>`<section class="workout-studio">${tab==='player'?'':`<nav class="ws-nav" aria-label="Workout tools">${[['tools','Studio'],['volume','Volume'],['records','Records'],['config','Setup']].map(([id,l])=>b(l,id,`aria-current="${tab===id?'page':'false'}"`,'ws-tab')).join('')}</nav>`}${content}</section>`;
 const show=(title,html,setup=()=>{})=>{clearInterval(restInterval);restInterval=null;const mode=title==='Correct your session'?'editRecord':title==='Review your session'?'review':title==='Training setup'?'config':title==='Live session'?'player':title==='Weekly training volume'?'volume':title==='Records & milestones'?'records':'tools';ctx.setDraftRoute?.({module:'workouts',mode,sessionId:configSession,...(mode==='editRecord'?recordRoute:{})});ctx.openSheet(title,html,setup);};
 function open(mode='tools'){
  if(mode==='resume')return resume();if(mode==='volume')return volume();if(mode==='records')return records();if(mode==='config')return config();
  const next=nextSession(data(),date()),sessions=data().training.sessions.filter(s=>s.exercises.length);
  show('Workout studio',shell(`${clearance()}<div class="ws-intro"><span class="eyebrow">YOUR TRAINING, IN FOCUS</span><h3>Make every set count.</h3><p>Record only the work you perform. Your plan and last results stay close.</p></div>${draft?`<div class="ws-resume"><div><b>${esc(draft.name)}</b><span>${esc(draft.date)} · ${setCount()} performed sets · local draft</span></div>${b('Resume','resume','','btn')}</div>`:''}<h4>Choose a session</h4><div class="ws-session-list">${sessions.map(s=>b(`<span><b>${esc(s.name)}</b><small>${esc(s.focus)} · ${s.exercises.length} movements${s.id===next?.id?' · Next in rotation':''}</small></span><span aria-hidden="true">${ctx.icon?.('arrow')||'<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor"><path d="M4 12h16m-6-6 6 6-6 6"/></svg>'}</span>`,'start',`data-ws-id="${esc(s.id)}"`,'ws-session')).join('')}</div>${note('Nothing is saved to your health record until you review and save. A completed prescribed session advances your rotation; a partial session does not.')}`));
 }
 function startSession(sessionId){
  const session=data().training.sessions.find(s=>s.id===(sessionId||nextSession(data(),date())?.id));
  if(!session?.exercises.length){ctx.toast?.('This is a recovery day. Use the rest-day log to record it.');return;}
  if(draft){show('Keep your current session?',shell(`<h3 class="sheet-hero-title">${esc(draft.name)}</h3>${note(`${setCount()} performed sets are saved in a local draft. Resume it, or explicitly replace it with ${esc(session.name)}.`)}<div class="ws-actions">${b('Resume existing','resume','','btn')}${b('Replace local draft','replace',`data-ws-id="${esc(session.id)}"`)}${b('Back to studio','tools')}</div>`));return;}
  draft=createSessionDraft(data(),session.id,date(),uid);draft.units=units();keep();player();
 }
 function resume(){if(!draft){ctx.toast?.('No workout draft to resume.');return open();}player();}
 function player(){
  if(!draft)return open();draft.index=Math.max(0,Math.min(draft.exercises.length-1,draft.index||0));
  const e=draft.exercises[draft.index],demo=findExerciseDemo(e.name),timed=/sec/i.test(e.reps),entry=draft.entries?.[draft.index]||{},last=previousPerformance(data(),e.name,shiftDate(draft.date,-1)),cfg=workoutConfig(data()),group=cfg.supersets?.[draft.sessionId]?.find(g=>g.includes(e.originalName)),sets=e.setLog,working=sets.filter(s=>s.kind==='working').length;
  const previous=last?`${esc(last.date)} · ${last.sets.length} recorded sets${last.exercise.reps!=null?` · ${esc(last.exercise.reps)} reps`:''}${last.exercise.load!=null?` · ${fmt(loadValue(last.exercise.load,draft.units))} ${loadLabel(draft.units)}`:''}`:'No previous recorded performance for this movement.';
  const lastSet=last?.sets.filter(s=>!s.legacy).at(-1)||last?.sets.at(-1);
  const content=shell(`${clearance()}<div class="ws-player-top"><div><span class="eyebrow">${esc(draft.name)} · ${esc(draft.date)}</span><p class="ws-local">${setCount()} performed sets · saved locally</p></div>${b('Review','review','','btn secondary small')}</div><div class="ws-progress" aria-label="Exercise ${draft.index+1} of ${draft.exercises.length}">${draft.exercises.map((ex,i)=>b(`<span>${i+1}</span>`,'exercise',`data-ws-index="${i}" aria-pressed="${draft.index===i}" aria-label="${esc(ex.name)}, ${ex.setLog.length} performed sets"`,ex.setLog.length?'ws-dot has-sets':'ws-dot')).join('')}</div><div class="ws-exercise-heading"><span class="eyebrow">MOVEMENT ${String(draft.index+1).padStart(2,'0')} / ${String(draft.exercises.length).padStart(2,'0')}</span><h3>${esc(e.name)}</h3>${e.originalName!==e.name?`<p>Substituted for ${esc(e.originalName)}</p>`:''}<p>${esc(e.sets)} × ${esc(e.reps)}${timed?'':' reps'} prescribed · ${Number(e.rest)||60}s rest</p></div>${demo?`<div class="ws-inline-demo"><div class="exercise-demo-stage" data-exercise-demo="${esc(demo.id)}" role="img" aria-label="Looping illustration of ${esc(e.name)}"><span class="demo-loading">Preparing your movement</span></div><div class="demo-transport"><button type="button" data-demo-toggle aria-label="Pause demonstration">Pause</button><span data-demo-phase>Controlled movement</span>${b('Technique & angles','demo','','ws-demo-details')}</div></div>`:''}${group?`<p class="ws-superset">Superset · ${group.map(esc).join(' + ')}<span>Alternate after a working set; rest after the round.</span></p>`:''}<details class="ws-previous"><summary>Previous recorded performance</summary><p>${previous}</p></details><form id="ws-set-form" class="ws-set-form"><div class="ws-set-heading"><h4>Record a performed set</h4><span>${working} / ${esc(e.sets)} working sets</span></div><div class="ws-input-grid">${field('reps',timed?'Seconds held':'Reps performed',entry.reps,`type="number" inputmode="numeric" min="1" max="${timed?3600:1000}" step="1" placeholder="${lastSet?.reps!=null&&!timed?'Last: '+lastSet.reps:'Unknown'}" data-ws-field="reps"`)}${field('load',`Load (${loadLabel(draft.units)})`,entry.load,`type="number" inputmode="decimal" min="0" max="${draft.units==='imperial'?2204.6226:1000}" step="any" placeholder="${lastSet?.load!=null?'Last: '+fmt(loadValue(lastSet.load,draft.units)):'Unknown'}" data-ws-field="load"`)}<label class="field">Set type<select name="kind" data-ws-field="kind"><option value="working" ${entry.kind!=='warmup'?'selected':''}>Working set</option><option value="warmup" ${entry.kind==='warmup'?'selected':''}>Warm-up set</option></select></label></div><details class="ws-effort" ${entry.rir||entry.rpe?'open':''}><summary>Optional effort · RIR / RPE</summary><div class="ws-input-grid">${field('rir','Reps in reserve',entry.rir,'type="number" inputmode="decimal" min="0" max="10" step="0.5" placeholder="Unknown" data-ws-field="rir"')}${field('rpe','Perceived effort (1–10)',entry.rpe,'type="number" inputmode="decimal" min="1" max="10" step="0.5" placeholder="Unknown" data-ws-field="rpe"')}</div><p class="help">RIR is how many more repetitions you could do. RPE is your effort rating. Both are optional.</p></details><p class="help">Load is the value you use for this movement, e.g. per dumbbell. Keep that convention consistent. Blank fields remain unknown.</p><p class="form-error" id="ws-error" role="alert"></p>${b('✓ I performed this set','complete','','btn full')}</form><div class="ws-rest" data-ws-rest aria-live="polite"></div>${sets.length?`<div class="ws-set-log"><h4>Performed sets</h4>${sets.map((s,i)=>`<div class="ws-set-row"><span>${i+1}</span><div><b>${s.kind==='warmup'?'Warm-up':'Working'} · ${timed?`${fmt(s.durationSec)} sec`:`${fmt(s.reps)} reps`} · ${fmt(loadValue(s.load,draft.units))} ${loadLabel(draft.units)}</b><small>${s.rir!=null?'RIR '+fmt(s.rir):''}${s.rir!=null&&s.rpe!=null?' · ':''}${s.rpe!=null?'RPE '+fmt(s.rpe):''}${s.rir==null&&s.rpe==null?'Effort not recorded':''}</small></div>${b('Undo','undo-set',`data-ws-index="${i}" aria-label="Undo performed set ${i+1}"`,'ws-undo')}</div>`).join('')}</div>`:''}${e.note?`<details class="ws-effort"><summary>Your program notes</summary><p class="help">${esc(e.note)}</p></details>`:''}<div class="ws-actions">${b('Previous movement','previous',draft.index===0?'disabled':'')}${b('Next movement','next',draft.index===draft.exercises.length-1?'disabled':'')}${b('Substitute movement','substitute')}${b('Review and save','review','','btn')}${b('Back to studio','tools')}</div>`,'player');
  show('Live session',content,()=>{const form=ctx.sheet.querySelector('#ws-set-form');form?.addEventListener('submit',ev=>{ev.preventDefault();complete();});updateRest();restInterval=setInterval(updateRest,1000);ctx.onSheetCleanup?.(()=>{clearInterval(restInterval);restInterval=null;});});
 }
 function capture(){if(!draft)return;const form=ctx.sheet.querySelector('#ws-set-form');if(!form)return;draft.entries??={};draft.entries[draft.index]=Object.fromEntries(['reps','load','kind','rir','rpe'].map(k=>[k,form.elements.namedItem(k)?.value||'']));keep();}
 function updateRest(){const target=ctx.sheet.querySelector('[data-ws-rest]');if(!target||!draft)return;const left=Math.ceil(((draft.restUntil||0)-Date.now())/1000);target.innerHTML=left>0?`<span>REST</span><strong>${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}</strong>${b('Skip rest','skip-rest','','ws-undo')}`:draft.restUntil?'<span>REST COMPLETE</span><b>Ready when you are.</b>':'';}
 function complete(){
  capture();try{const e=draft.exercises[draft.index];if(e.setLog.length>=100)throw Error('This exercise already has 100 performed sets.');const set=completedSet(draft.entries?.[draft.index]||{},{id:uid,timed:/sec/i.test(e.reps),imperial:draft.units==='imperial'});e.setLog.push(set);delete draft.entries[draft.index];
    const next=set.kind==='working'?supersetNext(draft,draft.index,workoutConfig(data()).supersets?.[draft.sessionId]||[]):{index:draft.index,rest:true};
    if(next.rest){draft.restUntil=Date.now()+(Number(e.rest)||60)*1000;ctx.startTimer?.(Number(e.rest)||60);}else{draft.restUntil=null;ctx.toast?.('Set recorded. Continue to the next superset movement.');}
    draft.index=next.index;keep();player();
  }catch(error){const target=ctx.sheet.querySelector('#ws-error');if(target)target.textContent=error.message;else ctx.toast?.(error.message);}
 }
 function review(){
  capture();if(!draft)return open();const performed=draft.exercises.filter(e=>e.setLog.length),elapsed=Math.max(0,Math.round((Date.now()-new Date(draft.startedAt).getTime())/60000));
  show('Review your session',shell(`<h3 class="sheet-hero-title">${esc(draft.name)}</h3>${note(`${esc(draft.date)} · ${setCount()} performed sets across ${performed.length} movements. Unperformed prescribed sets are excluded.`)}${performed.length?`<div class="ws-review-list">${performed.map(e=>`<div><b>${esc(e.name)}</b><span>${e.setLog.filter(s=>s.kind==='working').length} working · ${e.setLog.filter(s=>s.kind==='warmup').length} warm-up</span></div>`).join('')}</div>`:''}<form id="ws-review-form"><label class="field">Session status<select name="status"><option value="partial">Partial — preserve the current rotation</option><option value="completed">I completed this prescribed session — advance rotation</option></select></label>${field('duration','Actual duration (minutes)','','type="number" inputmode="decimal" min="0" max="1440" step="any" placeholder="Unknown"')}<p class="help">${elapsed} minutes have elapsed since opening the draft; this is not assumed to be your workout duration.</p><label class="field">Session notes<textarea name="notes" maxlength="5000" rows="3">${esc(draft.notes||'')}</textarea></label><p class="help">These records are saved in your public GitHub repository.</p>${ctx.saveFooter('Save performed sets')}</form><div class="ws-actions">${b('Back to session','resume')}${b('Discard local draft','discard')}</div>`),()=>ctx.wireForm(async fd=>{
    const record=sessionRecord(draft,{status:fd.get('status'),durationMin:fd.get('duration')===''?null:Number(fd.get('duration')),notes:fd.get('notes')}),savedDate=draft.date;
    await ctx.save(candidate=>{const day=ensureDay(candidate,savedDate);if(day.workouts.some(w=>w.id===record.id)||day.food.some(f=>f.id===record.id))throw Error('This session ID is already saved. Review your records before retrying.');day.workouts.push(record);},`Log performed sets for ${savedDate}`);draft=null;keep();
  }));
 }
 function substitute(){
  capture();if(!draft)return open();const e=draft.exercises[draft.index],cfg=workoutConfig(data()),options=substitutionOptions(e.originalName,cfg.equipment||[]);
  show('Choose a substitution',shell(`<h3 class="sheet-hero-title">${esc(e.name)}</h3>${note('Alternatives share a recorded muscle group. Equipment matching is not a statement that a movement suits an injury or restriction. Choose an appropriate movement yourself. Your prescription remains unchanged.')}<p class="ws-local">${cfg.equipment?.length?'Filtered to your selected equipment.':'No equipment filter selected. Choose equipment in Setup to narrow this list.'}</p>${e.setLog.length?'<p class="ws-clearance">This movement already has performed sets. Undo those local sets before replacing it, or finish the session and start a new one.</p>':`<div class="ws-session-list">${[{name:e.originalName},...options].filter((v,i,a)=>a.findIndex(x=>x.name===v.name)===i).map(d=>b(`<span><b>${esc(d.name)}</b><small>${esc(findExerciseDemo(d.name)?.equipment||'Original prescribed movement')}</small></span>`,'choose-substitute',`data-ws-name="${esc(d.name)}"`,'ws-session')).join('')}</div>`}<div class="ws-actions">${b('Back to session','resume')}${b('Equipment setup','config')}</div>`));
 }
 function volume(){const v=weeklyVolume(data(),date()),max=Math.max(1,...v.exercises.map(e=>e.sets));show('Weekly training volume',shell(`<div class="ws-intro"><span class="eyebrow">${esc(v.start)} — ${esc(v.end)}</span><h3>Your recorded work.</h3><p>Actual sets only. Warm-ups are kept separate.</p></div><div class="ws-stat-grid"><div><strong>${v.sets}</strong><span>working sets</span></div><div><strong>${v.warmupSets}</strong><span>warm-up sets</span></div><div><strong>${fmt(loadValue(v.knownVolume))}</strong><span>known ${loadLabel()} × reps</span></div></div>${v.exercises.length?`<h4>By movement</h4><div class="ws-volume-list">${v.exercises.map(e=>`<div><div><b>${esc(e.name)}</b><span>${e.sets} sets</span></div><span class="ws-volume-track"><i style="width:${e.sets/max*100}%"></i></span></div>`).join('')}</div><h4>By muscle group</h4><div class="ws-muscles">${v.muscles.map(m=>`<div><span>${esc(m.name)}</span><b>${m.sets}</b></div>`).join('')}</div>${note('A compound set appears in each mapped muscle group, so muscle totals overlap. Historical sets without set types are counted as recorded sets; only explicitly marked warm-ups are excluded.')} ${v.unmappedSets?note(`${v.unmappedSets} sets have no confirmed muscle mapping.`):''}${v.unknownVolumeSets?note(`${v.unknownVolumeSets} sets lack numeric reps or load, or are timed holds; they are excluded from kg × reps.`):''}`:note('No actual sets have been recorded this week. Prescribed sessions do not count toward volume.')}`, 'volume'));}
 function records(){const prs=personalRecords(data(),date()),cfg=workoutConfig(data());show('Records & milestones',shell(`<div class="ws-intro"><span class="eyebrow">SUPPORTED BY YOUR LOG</span><h3>Your personal records.</h3><p>Working sets only. Unknown reps or loads never become records.</p></div>${prs.length?`<div class="ws-record-list">${prs.map(r=>`<article><h4>${esc(r.name)}</h4><div>${r.maxLoad?`<span>Heaviest recorded load<b>${fmt(loadValue(r.maxLoad.value))} ${loadLabel()}</b><small>${esc(r.maxLoad.date)}</small></span>`:''}${r.maxReps?`<span>Most recorded reps in a set<b>${fmt(r.maxReps.value)}</b><small>${esc(r.maxReps.date)}</small></span>`:''}</div></article>`).join('')}</div>`:note('No numeric working-set records yet. Older set-only records remain in your history.')}<h4>Your progression rules</h4>${Object.entries(cfg.progression||{}).length?Object.entries(cfg.progression).map(([name,rule])=>{const last=previousPerformance(data(),name,date()),status=last?progressionStatus(last.exercise,rule):{met:false,reason:'No recorded performance yet.'};return`<div class="ws-milestone ${status.met?'met':''}"><b>${status.met?'✓ ':''}${esc(name)}</b><span>${rule.sets} working sets × ${rule.reps} reps${rule.load!=null?' · ≥ '+fmt(loadValue(rule.load))+' '+loadLabel():''}${rule.rir!=null?' · ≥ '+rule.rir+' RIR':''}</span><p>${esc(status.reason)}</p></div>`;}).join(''):note('Choose a rule in Setup. Meeting a rule is a recorded milestone, not an automatic increase to your plan.')}<div class="ws-actions">${b('Set progression rules','config')}</div>`,'records'));}
 function config(){
  const baseline=structuredClone(workoutConfig(data())),sessions=data().training.sessions.filter(s=>s.exercises.length);if(!sessions.some(s=>s.id===configSession))configSession=sessions[0]?.id;const session=sessions.find(s=>s.id===configSession),names=[...new Set(sessions.flatMap(s=>s.exercises.map(e=>e.name)))];
  const content=shell(`<h3 class="sheet-hero-title">Your training setup.</h3>${note('Equipment, substitutions and grouping are your preferences. They never mark sets performed or change your prescribed program.')}<form id="ws-config-form"><h4>Available equipment</h4><div class="ws-equipment">${EQUIPMENT.map(([id,label])=>`<label><input type="checkbox" name="equipment" value="${id}" ${baseline.equipment?.includes(id)?'checked':''}><span>${label}</span></label>`).join('')}</div><p class="help">No selection means no equipment filter. Save before choosing substitutions.</p><label class="field">Configure session<select name="session" data-ws-config-session>${sessions.map(s=>`<option value="${esc(s.id)}" ${s.id===configSession?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${session?`<h4>Preferred substitutions</h4>${session.exercises.map((e,i)=>`<label class="field">${esc(e.name)}<select name="sub-${i}"><option value="">Original prescription</option>${[...substitutionOptions(e.name,baseline.equipment||[]),...(baseline.substitutions?.[session.id]?.[e.name]?[{name:baseline.substitutions[session.id][e.name]}]:[])].filter((e,i,a)=>a.findIndex(x=>x.name===e.name)===i).map(o=>`<option value="${esc(o.name)}" ${baseline.substitutions?.[session.id]?.[e.name]===o.name?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`).join('')}<h4>Superset groups</h4>${(baseline.supersets?.[session.id]||[]).map((g,i)=>`<label class="ws-existing-group"><input type="checkbox" name="keep-group" value="${i}" checked><span>${g.map(esc).join(' + ')}</span></label>`).join('')}<p class="help">Choose two or more movements to add a group. Uncheck an existing group to remove it. A movement can belong to one group.</p><div class="ws-equipment">${session.exercises.map((e,i)=>`<label><input type="checkbox" name="group-exercise" value="${i}"><span>${esc(e.name)}</span></label>`).join('')}</div>`:''}<h4>Add or replace a progression rule</h4><label class="field">Movement<select name="rule-name"><option value="">No rule change</option>${names.filter(n=>!data().training.sessions.flatMap(s=>s.exercises).find(e=>e.name===n&&/sec/i.test(e.reps))).map(n=>`<option>${esc(n)}</option>`).join('')}</select></label><div class="ws-input-grid">${field('rule-sets','Working sets','','type="number" inputmode="numeric" min="1" max="100" step="1" placeholder="e.g. 3"')}${field('rule-reps','Minimum reps per set','','type="number" inputmode="numeric" min="1" max="1000" step="1" placeholder="e.g. 12"')}${field('rule-load',`Minimum load (${loadLabel()}, optional)`,'','type="number" inputmode="decimal" min="0" max="1000" step="any" placeholder="Any load"')}${field('rule-rir','Minimum RIR (optional)','','type="number" inputmode="decimal" min="0" max="10" step="0.5" placeholder="Any effort"')}</div>${Object.keys(baseline.progression||{}).length?`<h4>Keep existing rules</h4><div class="ws-equipment">${Object.keys(baseline.progression).map(n=>`<label><input type="checkbox" name="keep-rule" value="${esc(n)}" checked><span>${esc(n)}</span></label>`).join('')}</div>`:''}${ctx.saveFooter('Save training setup')}</form>`,'config');
  show('Training setup',content,()=>ctx.wireForm(async fd=>{
    const cfg=structuredClone(baseline);cfg.equipment=fd.getAll('equipment');cfg.substitutions??={};cfg.supersets??={};cfg.progression??={};if(session){cfg.substitutions[session.id]={};session.exercises.forEach((e,i)=>{const value=fd.get(`sub-${i}`);if(value)cfg.substitutions[session.id][e.name]=value;});
      let groups=(baseline.supersets?.[session.id]||[]).filter((_,i)=>fd.getAll('keep-group').includes(String(i)));const selected=fd.getAll('group-exercise').map(i=>session.exercises[Number(i)]?.name).filter(Boolean);if(selected.length===1)throw Error('Select at least two movements for a superset, or leave all unselected.');if(selected.length>1){if(groups.some(g=>g.some(n=>selected.includes(n))))throw Error('Remove the existing overlapping group before creating this superset.');groups.push(selected);}cfg.supersets[session.id]=groups;
    }
    for(const name of Object.keys(cfg.progression))if(!fd.getAll('keep-rule').includes(name))delete cfg.progression[name];const ruleName=fd.get('rule-name');if(ruleName){const read=(k,min,max,integer=false)=>{const raw=fd.get(k);if(raw==='')return null;const n=Number(raw);if(!Number.isFinite(n)||n<min||n>max||(integer&&!Number.isInteger(n)))throw Error('Enter valid progression thresholds.');return n;};const sets=read('rule-sets',1,100,true),reps=read('rule-reps',1,1000,true);if(sets==null||reps==null)throw Error('A progression rule requires working sets and reps.');const rawLoad=read('rule-load',0,units()==='imperial'?2204.6226:1000);cfg.progression[ruleName]={sets,reps,load:rawLoad==null?null:Math.round((units()==='imperial'?rawLoad/2.20462262185:rawLoad)*10000)/10000,rir:read('rule-rir',0,10)};}
    await ctx.save(candidate=>{assertUnchanged(workoutConfig(candidate),baseline);candidate.tracker??={};candidate.tracker.workouts=cfg;},'Update training setup');
  }));
 }
 function editRecord(record,recordDate=date()){
  const current=data().days[recordDate]?.workouts.find(w=>w.id===record?.id);if(!current){ctx.toast?.('That session no longer exists. Refresh your records.');return;}const baseline=structuredClone(current),editUnits=units();recordRoute={recordId:baseline.id,date:recordDate,units:editUnits};
  const input=(key,label,value,attrs)=>field(key,label,value,attrs);
  const rows=(baseline.actualExercises||[]).map((e,ei)=>`<section class="ws-correct-exercise"><h4>${esc(e.name)}</h4>${Array.isArray(e.setLog)?e.setLog.map((set,si)=>{const key=`set-${ei}-${si}`,timed=e.measure==='seconds';return `<details class="ws-correct-set" ${si===0?'open':''}><summary><span>Set ${si+1} · ${set.kind==='warmup'?'Warm-up':'Working'}</span><small>${timed?`${fmt(set.durationSec)} sec`:`${fmt(set.reps)} reps`} · ${fmt(loadValue(set.load,editUnits))} ${loadLabel(editUnits)}</small></summary><div class="ws-input-grid">${input(key+'-reps',timed?'Seconds held':'Reps performed',timed?set.durationSec:set.reps,`type="number" inputmode="numeric" min="1" max="${timed?3600:1000}" step="1" placeholder="Unknown"`)}${input(key+'-load',`Load (${loadLabel(editUnits)})`,loadValue(set.load,editUnits),`type="number" inputmode="decimal" min="0" max="${editUnits==='imperial'?2204.6226:1000}" step="any" placeholder="Unknown"`)}<label class="field">Set type<select name="${key}-kind"><option value="working" ${set.kind==='working'?'selected':''}>Working set</option><option value="warmup" ${set.kind==='warmup'?'selected':''}>Warm-up set</option></select></label>${input(key+'-rir','Reps in reserve',set.rir,'type="number" inputmode="decimal" min="0" max="10" step="0.5" placeholder="Unknown"')}${input(key+'-rpe','Perceived effort (1–10)',set.rpe,'type="number" inputmode="decimal" min="1" max="10" step="0.5" placeholder="Unknown"')}</div><label class="ws-existing-group"><input type="checkbox" name="${key}-remove"><span>Remove this incorrectly recorded set</span></label><p class="ws-local">Original completion time: ${esc(set.completedAt)}. It will be preserved.</p></details>`;}).join(''):`<p class="help">${fmt(e.sets)} recorded sets · ${esc(e.reps??'unknown')} reps · ${fmt(loadValue(e.load,editUnits))} ${loadLabel(editUnits)}. This earlier aggregate entry is preserved as recorded.</p>`}</section>`).join('');
  show('Correct your session',shell(`<p class="ws-local">${esc(recordDate)} · Corrections to the original record</p><form id="ws-record-edit-form">${input('name','Session name',baseline.name,'required maxlength="500"')}<label class="field">Session status<select name="status"><option value="partial" ${baseline.status==='partial'?'selected':''}>Partial — preserve rotation position</option><option value="completed" ${baseline.status==='completed'?'selected':''}>Completed prescribed session — affects rotation</option></select></label>${input('duration','Actual duration (minutes)',baseline.durationMin,'type="number" inputmode="decimal" min="0" max="1440" step="any" placeholder="Unknown"')}<label class="field">Session notes<textarea name="notes" maxlength="5000" rows="3">${esc(baseline.notes||'')}</textarea></label><p class="help">Edit only what you want to correct. Blank performance stays unknown. Set identities, completion times and unrelated metadata are retained.</p>${rows}${ctx.saveFooter('Save session corrections')}</form>${ctx.button?`<div class="ws-actions">${ctx.button('Delete entire session','workout-delete','','btn secondary',`data-id="${esc(baseline.id)}" data-for-date="${esc(recordDate)}"`)}</div>`:''}`),()=>ctx.wireForm(async fd=>{
    const sets=[];for(const[ei,e]of(baseline.actualExercises||[]).entries())for(const[si,set]of(e.setLog||[]).entries()){const key=`set-${ei}-${si}`;sets.push({exerciseIndex:ei,setId:set.id,remove:fd.has(key+'-remove'),values:Object.fromEntries(['reps','load','kind','rir','rpe'].map(k=>[k,fd.get(key+'-'+k)]))});}
    const revised=correctWorkoutRecord(baseline,{name:fd.get('name'),status:fd.get('status'),durationMin:fd.get('duration')===''?null:Number(fd.get('duration')),notes:fd.get('notes'),sets},{imperial:editUnits==='imperial'});
    await ctx.save(candidate=>{const day=candidate.days[recordDate],index=day?.workouts.findIndex(w=>w.id===baseline.id)??-1;if(index<0)throw Error('This session was removed elsewhere. Nothing was overwritten.');assertUnchanged(day.workouts[index],baseline);day.workouts[index]=revised;},`Correct performed sets for ${recordDate}`);
  }));
 }
 function handleClick(event){const el=event.target.closest('[data-ws]');if(!el||el.disabled)return false;event.preventDefault();const act=el.dataset.ws;
  try{if(['tools','volume','records','config','resume'].includes(act)){capture();open(act);}else if(act==='start')startSession(el.dataset.wsId);else if(act==='replace'){draft=null;keep();startSession(el.dataset.wsId);}else if(act==='exercise'||act==='previous'||act==='next'){capture();draft.index=act==='exercise'?Number(el.dataset.wsIndex):draft.index+(act==='previous'?-1:1);keep();player();}else if(act==='complete')complete();else if(act==='undo-set'){capture();draft.exercises[draft.index].setLog.splice(Number(el.dataset.wsIndex),1);keep();player();}else if(act==='skip-rest'){draft.restUntil=null;keep();updateRest();}else if(act==='review')review();else if(act==='discard'){draft=null;keep();open();}else if(act==='substitute')substitute();else if(act==='choose-substitute'){const e=draft.exercises[draft.index];if(e.setLog.length)throw Error('Undo the performed sets before replacing this movement.');e.name=el.dataset.wsName;keep();player();}else if(act==='demo'){capture();const e=draft.exercises[draft.index];ctx.openExerciseStudio({title:draft.name,sessionId:draft.sessionId,exercises:[e],prescribed:true,back:()=>player()},0);}return true;
  }catch(error){ctx.toast?.(error.message);return true;}
 }
 function handleInput(event){if(event.target.matches('[data-ws-field]'))capture();if(event.target.closest('#ws-review-form')&&event.target.name==='notes'&&draft){draft.notes=event.target.value;keep();}}
 function handleChange(event){if(event.target.matches('[data-ws-config-session]')){configSession=event.target.value;config();return true;}if(event.target.matches('[data-ws-field]')){capture();return true;}return false;}
 function restoreDraftRoute(route){if(route.mode==='editRecord'){const record=data().days[route.date]?.workouts.find(w=>w.id===route.recordId);if(record)editRecord(record,route.date);else ctx.toast?.('That session no longer exists. Its draft has been kept.');}else if(route.mode==='config'){configSession=route.sessionId;config();}else if(route.mode==='review'&&draft)review();else if(route.mode==='player'&&draft)resume();else open(route.mode);}return{open,handleClick,handleInput,handleChange,startSession,resume,editRecord,restoreDraftRoute,hasDraft:()=>Boolean(draft),draftSummary:()=>draft?{name:draft.name,date:draft.date,sets:setCount()}:null};
}
